use semio_framework_test_fixtures::fixture_text;
use super::*;
use crate::retained_clone::{RetainedCloneSource,RetainedCloneStep};
pub(super) fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
pub(super) fn observe<T>(op:impl FnOnce()->T)->(T,(usize,usize)){crate::value::observe_retirement_allocations(op)}
pub(super) fn original<T:RetireOwned+Sync+'static>(value:T)->RetainedCloneSource<T>{let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:4096};match RetainedCloneSource::admit_owned(value,(),g){Ok((s,_))=>s,Err((e,_,_))=>panic!("{e}")}}
pub(super) fn close_source<T:RetireOwned+Sync+'static>(s:&mut RetainedCloneSource<T>){let mut turns=0;let mut idle=0;while !s.terminal_is_empty(){let g=grant(RetirementDemand{copy_bytes:s.next_close_copy_byte_demand().unwrap(),capacity_bytes:s.next_close_capacity_byte_demand(4096).unwrap(),release_bytes:s.next_close_release_byte_demand().unwrap(),depth:s.next_close_depth_demand().unwrap()});let step=s.close_step(g).unwrap();if step.progress()==Default::default(){idle+=1;assert!(idle<8,"persistent source closure repeats an inert exact quote: {g:?}");}else{idle=0;}turns+=1;assert!(turns<1000000);}}
pub(super) fn row(value:i64)->SealedShared<i64>{let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:size_of::<i64>()*2,maximum_capacity_bytes:SealedShared::<i64>::birth_bytes(),maximum_release_bytes:0,maximum_depth:1};match SealedShared::admit(value,SharedIssuer::owned(),g){Ok((r,_))=>r,Err((e,_))=>panic!("{e}")}}
pub(super) fn list(count:usize)->PersistentList<i64>{let mut level=Vec::new();for start in(0..count).step_by(PERSISTENT_PAGE_FANOUT){let len=(count-start).min(PERSISTENT_PAGE_FANOUT);let rows=std::array::from_fn(|index|if index<len{Some(row(((start+index)*2)as i64))}else{None});match PersistentList::admit_leaf(rows,len,grant(PersistentList::<i64>::page_birth_demand())){Ok((page,_))=>level.push(page),Err((e,_))=>panic!("{e}")}}while level.len()>1{let mut next=Vec::new();let mut nodes=level.into_iter();loop{let children=std::array::from_fn(|_|nodes.next());if children[0].is_none(){break;}match PersistentList::admit_branch(children,grant(PersistentList::<i64>::page_birth_demand())){Ok((page,_))=>next.push(page),Err((e,_))=>panic!("{e}")}}level=next;}level.pop().unwrap()}
fn close(plan:&mut PersistentSet<i64>){plan.begin_close();let mut turns=0;while !plan.terminal_is_empty(){let g=grant(plan.close_demand(4096).unwrap());let(s,h)=observe(||plan.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));assert!(turns<50||s.progress()!=Default::default(),"persistent plan closure repeats inert quote: {g:?}");turns+=1;assert!(turns<10000,"immutable page cancellation stalled: {g:?}");}}
mod quick {
use super::*;
/// 🌳️ Original immutable readers and untouched rows keep their identities through exactly one changed path.
#[test]
fn persistent_shared_pages_preserve_readers_and_birth_only_changed_paths(){
 let corpus:serde_json::Value=serde_json::from_str(fixture_text!("../../🧪️tests/🧫️fixtures/🔣️.json")).unwrap();
 for case in corpus["cases"].as_array().unwrap(){let count=case["rowCount"].as_u64().unwrap()as usize;let index=case["index"].as_u64().unwrap()as usize;let mut source=original(list(count));let mut authored=original(row(case["authored"].as_i64().unwrap()));let old_root=source.borrow().get().root.as_ref().unwrap().identity();
  let projection_quote=grant(PersistentList::<i64>::projection_demand());for g in[RetainedCloneGrant{maximum_items:0,..projection_quote},RetainedCloneGrant{maximum_copy_bytes:projection_quote.maximum_copy_bytes-1,..projection_quote},RetainedCloneGrant{maximum_depth:0,..projection_quote}]{let(result,h)=observe(||PersistentList::project(source.borrow(),g).unwrap());assert!(result.is_none());assert_eq!(h,(0,0));}
  let((reader,p),h)=observe(||PersistentList::project(source.borrow(),projection_quote).unwrap().unwrap());assert_eq!(h,(0,0));assert!(p.fits(projection_quote));assert_eq!(reader.root.as_ref().unwrap().identity(),old_root);let mut reader=original(reader);
  let mut plan=PersistentSet::new(index);let mut births=0;let mut turns=0;loop{let d=plan.demand(source.borrow(),authored.borrow()).unwrap();let g=grant(d);for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(s,h)=observe(||plan.advance(source.borrow(),authored.borrow(),denied).unwrap());assert_eq!(h,(0,0));assert_eq!(s.progress(),Default::default());}let(s,h)=observe(||plan.advance(source.borrow(),authored.borrow(),g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));if s.progress().retained_capacity_bytes>0{births+=1;}turns+=1;assert!(turns<1000);if matches!(s,RetainedCloneStep::Complete(_)){break;}}
  assert_eq!(births,case["changedPages"].as_u64().unwrap()as usize);assert_eq!(*source.borrow().get().get(index).unwrap(),case["before"].as_i64().unwrap());assert_eq!(*reader.borrow().get().get(index).unwrap(),case["unchangedReader"].as_i64().unwrap());
  let take=RetirementDemand{copy_bytes:size_of::<PersistentList<i64>>()*2+size_of::<SealedShared<Page<i64>>>(),depth:1,..Default::default()};let((candidate,p),h)=observe(||plan.take(grant(take)).unwrap().unwrap());assert_eq!(h,(0,0));assert!(p.fits(grant(take)));assert_ne!(candidate.root.as_ref().unwrap().identity(),old_root);
  for slot in 0..count{assert_eq!(*candidate.get(slot).unwrap(),if slot==index{case["after"].as_i64().unwrap()}else{(slot*2)as i64});if slot!=index{assert_eq!(candidate.get(slot).unwrap()as*const i64,source.borrow().get().get(slot).unwrap()as*const i64);}}
  let mut candidate=original(candidate);close(&mut plan);let(_,h)=observe(||drop(plan));assert_eq!(h,(0,0));close_source(&mut candidate);close_source(&mut reader);close_source(&mut authored);close_source(&mut source);
  eprintln!("[DEBUG] shared immutable pages {:?}: rows{count}, changed page births{births}, root projection alloc0, old reader stable, untouched row addresses preserved",case["id"]);
 }
}
/// 🛑️ Every original path frontier closes without replacing or mutating published roots.
#[test]
fn persistent_shared_pages_cancel_every_changed_path_frontier(){for frontier in 0..45{eprintln!("[DEBUG] persistent cancel frontier{frontier}: construction");let mut source=original(list(17));let mut authored=original(row(-7));let root=source.borrow().get().root.as_ref().unwrap().identity();let mut plan=PersistentSet::new(16);for _ in 0..frontier{let g=grant(plan.demand(source.borrow(),authored.borrow()).unwrap());if matches!(plan.advance(source.borrow(),authored.borrow(),g).unwrap(),RetainedCloneStep::Complete(_)){break;}}assert_eq!(source.borrow().get().root.as_ref().unwrap().identity(),root);assert_eq!(source.borrow().get().get(16),Some(&32));eprintln!("[DEBUG] persistent cancel frontier{frontier}: plan close");close(&mut plan);eprintln!("[DEBUG] persistent cancel frontier{frontier}: authored close");close_source(&mut authored);eprintln!("[DEBUG] persistent cancel frontier{frontier}: source close");close_source(&mut source);eprintln!("[DEBUG] persistent cancel frontier{frontier}: complete");}}
}

